import sys
import dataclasses
import itertools

import numpy as np
import opt_einsum as oe
import pytest

from nvmath.internal.utils import infer_object_package

from cuquantum import MemoryLimitExceeded
from cuquantum.tensornet import tensor, OptimizerInfo
from cuquantum.tensornet.experimental import contract_decompose, ContractDecomposeAlgorithm, ContractDecomposeInfo
from cuquantum.tensornet.experimental._internal.utils import is_gate_split
from cuquantum.tensornet._internal.decomposition_utils import DECOMPOSITION_DTYPE_NAMES, parse_decomposition

from ..test_options import _OptionsBase
from ..utils.approxTN_utils import split_contract_decompose, tensor_decompose, verify_split_QR, verify_split_SVD, SingularValueDegeneracyError
from ..utils.data import BACKEND_MEMSPACE, contract_decompose_expr
from ..utils.helpers import cleanup_between_tests
from ..utils.helpers import DecomposeFactory, Deselector, get_svd_methods_for_test
from ..utils.helpers import get_stream_for_backend, _BaseTester

NUM_TESTS_PER_CASE = 3

class BaseContractDecomposeTester(_BaseTester):

    def _get_config_iterator(self, *args, **kwargs):
        rng = self._get_rng(*args, **kwargs)
        TEST_CONFIGS = list(itertools.product(
            ["C", "F"], # order
            [None, True], # stream
        ))
        rng.shuffle(TEST_CONFIGS)
        return itertools.cycle(TEST_CONFIGS)

    def _run_contract_decompose(self, decompose_expr, xp, dtype, order, stream, algorithm, rng):
        if isinstance(decompose_expr, list):
            decompose_expr, options, optimize, kwargs = decompose_expr
        else:
            options, optimize, kwargs = {}, {}, {}
        return_info = kwargs.get('return_info', True)
        kwargs['return_info'] = return_info

        factory = DecomposeFactory(decompose_expr, rng)
        operands = factory.generate_operands(factory.input_shapes, xp, dtype, order)
        backend = sys.modules[infer_object_package(operands[0])]

        contract_expr, decomp_expr = split_contract_decompose(decompose_expr)
        _, input_modes, output_modes, _, _, _,  max_mid_extent= parse_decomposition(decompose_expr, *operands)
        if not is_gate_split(input_modes, output_modes, algorithm):
            if algorithm.qr_method is not False and algorithm.svd_method is not False: # QR assisted contract SVD decomposition
                pytest.skip("QR assisted SVD decomposition not support for more than three operands")

        shared_mode_out = (set(output_modes[0]) & set(output_modes[1])).pop()
        shared_mode_idx_left = output_modes[0].index(shared_mode_out)
        shared_mode_idx_right = output_modes[1].index(shared_mode_out)

        if stream:
            stream = get_stream_for_backend(backend)
        outputs = contract_decompose(decompose_expr, *operands, 
            algorithm=algorithm, stream=stream, options=options, optimize=optimize, **kwargs)

        if stream:
            stream.synchronize()

        #NOTE: The reference here is based on splitting the contract_decompose problem into two sub-problems
        #       - 1. contraction. The reference is based on opt_einsum contract
        #       - 2. decomposition. The reference is based on tensor_decompose in approxTN_utils
        # note that a naive reference implementation here may not find the optimal reduce extent, for example:
        # A[x,y] B[y,z] with input extent x=4, y=2, z=4 -> contract QR decompose -> A[x,k]B[k,z] . 
        # When naively applying the direct algorithm above, the mid extent k in the output will be 2.
        # This case is already consider in contract_decompose. Here make following modifications for correctness testing
        # For contract and QR decompose, we check the output extent is correct
        # For contract and SVD decompose, we inject this mid_extent in the args to the reference implementation when needed.
        intm = oe.contract(contract_expr, *operands)

        if algorithm.svd_method is False:
            if return_info:
                q, r, info = outputs
                assert isinstance(info, ContractDecomposeInfo)
            else:
                q, r = outputs
            assert type(q) is type(r)
            assert type(q) is type(operands[0])
            assert q.shape[shared_mode_idx_left] == max_mid_extent
            assert r.shape[shared_mode_idx_right] == max_mid_extent
            assert verify_split_QR(decomp_expr, intm, q, r, None, None)
        else:
            svd_kwargs = dataclasses.asdict(algorithm.svd_method)
            max_extent = svd_kwargs.get('max_extent')
            if max_extent in [0, None] or max_extent > max_mid_extent:
                svd_kwargs['max_extent'] = max_mid_extent
            try:
                outputs_ref = tensor_decompose(decomp_expr, intm, method="svd", return_info=return_info, **svd_kwargs)
            except SingularValueDegeneracyError:
                pytest.skip("Test skipped due to singular value degeneracy issue")
            if return_info:
                u, s, v, info = outputs
                assert isinstance(info, ContractDecomposeInfo)
                u_ref, s_ref, v_ref, info_ref = outputs_ref 
                info = info.svd_info
                assert isinstance(info, tensor.SVDInfo)
                info =  dataclasses.asdict(info)
            else:
                u, s, v = outputs
                u_ref, s_ref, v_ref = outputs_ref
                info = info_ref = None
            assert type(u) is type(v)
            assert type(u) is type(operands[0])
            if algorithm.svd_method.partition is None:
                assert type(u) is type(s)
            else:
                assert s is None
            assert verify_split_SVD(decomp_expr, 
                                    intm, 
                                    u, s, v, 
                                    u_ref, s_ref, v_ref,
                                    info=info,
                                    info_ref=info_ref,
                                    **svd_kwargs)

class TestContractDecomposeFunctionality(BaseContractDecomposeTester):

    @pytest.mark.parametrize(
        "stream", (None, True)
    )
    @pytest.mark.parametrize(
        "algorithm", [
            ContractDecomposeAlgorithm(qr_method=False, svd_method={}),
            ContractDecomposeAlgorithm(qr_method={}, svd_method=False),
        ]
    )
    def test_stream(self, algorithm, stream):
        xp = self._get_xp(algorithm, stream)
        decompose_expr = 'ijk,klm,jlpq->kpi,qmk'
        rng = self._get_rng(decompose_expr, xp, algorithm, stream, "stream")
        self._run_contract_decompose(decompose_expr, xp, "float64", "C", stream, algorithm, rng)

    @pytest.mark.parametrize(
        "order", ("C", "F")
    )
    @pytest.mark.parametrize(
        "algorithm", [
            ContractDecomposeAlgorithm(qr_method=False, svd_method={}),
            ContractDecomposeAlgorithm(qr_method={}, svd_method=False),
        ]
    )
    def test_order(self, algorithm, order):
        rng = self._get_rng(algorithm, order, "order")
        xp = self._get_xp(algorithm, order)
        decompose_expr = 'beQ,cey,cbJj->Je,jQey'
        self._run_contract_decompose(decompose_expr, xp, "complex128", order, None, algorithm, rng)


@pytest.mark.uncollect_if(func=Deselector.deselect_decompose_tests)
@pytest.mark.parametrize(
    "dtype", DECOMPOSITION_DTYPE_NAMES
)
@pytest.mark.parametrize(
    "xp", BACKEND_MEMSPACE
)
@pytest.mark.parametrize(
    "decompose_expr", contract_decompose_expr
)
class TestContractDecompose(BaseContractDecomposeTester):

    def test_contract_qr_decompose(self, decompose_expr, xp, dtype):
        rng = self._get_rng(decompose_expr, xp, dtype, "contract_qr_decompose")
        order, stream = next(self._get_config_iterator(decompose_expr, xp, dtype))
        algorithm = ContractDecomposeAlgorithm(qr_method={}, svd_method=False)
        self._run_contract_decompose(decompose_expr, xp, dtype, order, stream, algorithm, rng)

    @pytest.mark.parametrize(
        'qr_method', [False, {}] # QR-assisted SVD decomposition  and without QR
    )
    def test_contract_svd_decompose(self, decompose_expr, xp, dtype, qr_method):
        rng = self._get_rng(decompose_expr, xp, dtype, qr_method, "contract_svd_decompose")
        config_iter = self._get_config_iterator(decompose_expr, xp, dtype, qr_method)
        methods = get_svd_methods_for_test(NUM_TESTS_PER_CASE, dtype, rng)
        for svd_method in methods:
            order, stream = next(config_iter)
            algorithm = ContractDecomposeAlgorithm(qr_method=qr_method, svd_method=svd_method)
            self._run_contract_decompose(decompose_expr, xp, dtype, order, stream, algorithm, rng)

def test_memory_limit():
    decompose_expr = 'il->ix,lx'
    factory = DecomposeFactory(decompose_expr, np.random.default_rng(100))
    operands = factory.generate_operands(factory.input_shapes, "numpy", "float64", "C")
    with pytest.raises(MemoryLimitExceeded):
        contract_decompose(decompose_expr, *operands, options={'memory_limit': 1})


def test_output_only_mode_raises_value_error():
    """A mode appearing only in the outputs must be the shared mid extent mode.

    Otherwise no extent can be inferred for it, which used to surface as a KeyError
    while computing the mid extent.
    """
    decompose_expr = 'ab,bc->axd,xc'
    operands = [np.zeros((2, 3)), np.zeros((3, 4))]
    with pytest.raises(ValueError, match="contracted outcome"):
        parse_decomposition(decompose_expr, *operands)
    with pytest.raises(ValueError, match="contracted outcome"):
        contract_decompose(decompose_expr, *operands)


@pytest.mark.parametrize(
    "decompose_expr", ['ab,bc->aax,xc', 'ab,bc->axx,xc']
)
def test_repeated_output_mode_raises_value_error(decompose_expr):
    """The modes of each output tensor must be distinct.

    The contracted outcome of the outputs is compared against the inputs as sets, so
    repeated output modes have to be checked separately.
    """
    operands = [np.zeros((2, 3)), np.zeros((3, 4))]
    with pytest.raises(ValueError):
        parse_decomposition(decompose_expr, *operands)
    with pytest.raises(ValueError):
        contract_decompose(decompose_expr, *operands)


