def _make_qiskit_custom_kraus():
    from qiskit import QuantumCircuit
    from qiskit.quantum_info import Kraus
    K0 = np.array([[1, 0], [0, np.sqrt(0.7)]], dtype=complex)
    K1 = np.array([[0, np.sqrt(0.3)], [0, 0]], dtype=complex)
    qc = QuantumCircuit(2)
    qc.x(0)
    qc.h(1)
