class CirqCircuitMatrix(CircuitMatrixABC):

    @staticmethod
    def L0():
        return cirq_L0_circuits

    @staticmethod
    def L1():
        return cirq_L1_circuits

    @staticmethod
    def L2():
        return cirq_L2_circuits

    @staticmethod
    def realL0():
        if cirq is None:
