class CircuitMatrix(CircuitMatrixABC):

    @staticmethod
    def L0():
        return CirqCircuitMatrix.L0() + QiskitCircuitMatrix.L0()

    @staticmethod
    def L1():
        return CirqCircuitMatrix.L1() + QiskitCircuitMatrix.L1()

    @staticmethod
    def L2():
        return CirqCircuitMatrix.L2() + QiskitCircuitMatrix.L2()

    @staticmethod
    def realL0():
